const HALLSPOTS={"board": [80, 36, 340, 114], "belt": [40, 352, 800, 86], "shelf": [700, 240, 150, 62], "fair": [40, 300, 800, 40], "dungeon": [30, 150, 220, 180], "silvercity": [300, 10, 280, 320], "jacks": [604, 200, 262, 190]};

/* the halls you can touch: the arrivals board and belt, the library's new shelf, the expo stalls,
   the three club doors. Live radio can't pull a track forward, so a record card says when it arrives
   and where you can have it now. In the extension the same card opens it on YouTube. */
const HU=(()=>{
 const D=()=>{try{return data}catch(e){return undefined}},isLive=()=>{try{return typeof BASE!=='undefined'}catch(e){return false}},base=()=>{try{return BASE}catch(e){return ''}};
 const st=id=>{const d=D();return d&&d.stations?d.stations.find(s=>s.id===id):null};
 const ex=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const cov=t=>t&&t.cover?`${base()}/api/cover/${t.id}`:'';
 const mmss=s=>s<60?'under a minute':`${Math.floor(s/60)} min`;
 function etas(s){if(!s||!s.now)return[];const n=s.now,left=Math.max(0,(n.started||0)+(n.dur||0)-Date.now()/1e3);let acc=left;return(s.next||[]).map(t=>{const e=acc;acc+=t.dur||0;return{...t,eta:e}})}
 const pct=(x,y,w,h)=>`left:${x/8.8}%;top:${y/5}%;width:${w/8.8}%;height:${h/5}%`;
 const CLUBS={
  dungeon:['Dungeon','Concrete, one red lamp, a vault door. Cold minimal techno with a kinky side door: EBM, industrial, glamorous coldwave by night.'],
  silvercity:['Silvercity','A research institute under golden brains. Progressive and on the edge, a labyrinth of rooms, and still for dancing.'],
  jacks:["Jack's",'Chicago, 1985. A laid-back dancehall: deep house, soulful jacking, a veranda with string lights and a small floor outside.']};
 function card(html){let c=$('#hcard');if(!c){c=document.createElement('div');c.id='hcard';$('#stage').appendChild(c);c.addEventListener('click',e=>{if(e.target.closest('[data-x]'))c.classList.remove('on')})}c.innerHTML=html+'<button data-x aria-label="Close">×</button>';c.classList.add('on')}
 function rec(t,from){const s=st(from)||{},go=from&&from!==S.ch?`<button data-go="${from}">Go to ${ex(s.name||from)}</button>`:'';
  const yt=`https://www.youtube.com/results?search_query=${encodeURIComponent((t.artist||'')+' '+(t.title||''))}`;
  const act=isLive()?`<a href="${(()=>{try{return extUrl()}catch(e){return '#'}})()}">Play it now in the extension</a>`:`<a href="${yt}" target="_blank" rel="noopener">Open on YouTube</a>`;
  card(`${cov(t)?`<img src="${cov(t)}" alt="">`:''}<div><p class=k>${ex(s.name||'')}${t.on?' · on the belt now':t.eta!=null?` · arrives in ${mmss(t.eta)}`:''}</p><p class=t>${ex(t.title)}</p><p class=a>${ex(t.artist)}</p><p class=r>${act}${go}</p></div>`)}
 function club(k){const[n,d]=CLUBS[k];const dep=isLive()?(()=>{try{return SITE}catch(e){return '../'}})()+'#depot':'https://antonalter.github.io/rrradio/#depot';
  card(`<div><p class=k>Union Square · premium</p><p class=t>${n}</p><p class=a>${d}</p><p class=r><a href="${dep}" target="_blank" rel="noopener">Opens with Deepot</a></p></div>`)}
 function render(layer,ch){if(typeof HALLSPOTS==='undefined')return;const P=HALLSPOTS,s=st(ch),q=etas(s);let h='';
  if(ch==='fresh'){const rows=[s&&s.now?{...s.now,eta:0,on:1}:null,...q].filter(Boolean).slice(0,4);
   h+=`<div class="hs board" style="${pct(...P.board)}">${rows.map((t,i)=>`<button class=row data-t="${i}"><span>${t.on?'ON BELT':('RR '+(100+i*37))}</span><span>${ex(t.artist)} — ${ex(t.title)}</span><span>${t.on?'LANDED':mmss(t.eta)}</span></button>`).join('')||'<p class=row><span>— no arrivals listed —</span></p>'}</div>`;
   h+=`<div class="hs belt" style="${pct(...P.belt)}"><div class=run>${rows.concat(rows).map((t,i)=>`<button class=case data-t="${i%rows.length}" title="${ex(t.artist)} — ${ex(t.title)}"><i style="background-image:url('${cov(t)}')"></i></button>`).join('')}</div></div>`;
   layer._rows=rows}
  if(ch==='clock'){const b=q.slice(0,3);h+=`<div class="hs shelf" style="${pct(...P.shelf)}">${b.map((t,i)=>`<button class=book data-t="${i}" title="${ex(t.artist)} — ${ex(t.title)}"><i style="background-image:url('${cov(t)}')"></i></button>`).join('')}</div>`;layer._rows=b}
  if(ch==='global'){const all=D()&&D().stations?D().stations.filter(x=>x.next&&x.next[0]).map(x=>({...etas(x)[0],from:x.id})).slice(0,6):[];
   h+=`<div class="hs fair" style="${pct(...P.fair)}">${all.map((t,i)=>`<button class=stall data-t="${i}" style="left:${[1,14,27,64,77,90][i]}%" title="${ex(t.artist)} — ${ex(t.title)}"><i style="background-image:url('${cov(t)}')"></i></button>`).join('')}</div>`;layer._rows=all}
  if(ch==='club')['dungeon','silvercity','jacks'].forEach(k=>h+=`<button class="hs door" data-club="${k}" style="${pct(...P[k])}" aria-label="${CLUBS[k][0]}"></button>`);
  layer.innerHTML=h}
 function bind(layer,ch){layer.onclick=e=>{const b=e.target.closest('button');if(!b)return;e.stopPropagation();
  if(b.dataset.club)return club(b.dataset.club);const t=layer._rows&&layer._rows[+b.dataset.t];if(t)rec(t,t.from||ch)}}
 document.addEventListener('click',e=>{const g=e.target.closest('#hcard [data-go]');if(g){const b=document.querySelector(`[data-c="${g.dataset.go}"]`);if(b)b.click();$('#hcard').classList.remove('on')}});
 function opart(ch){/* op art as architecture: a floor of lines converging to the room's vanishing point, walls of horizontal courses
   whose spacing swells like a Riley field. Calm in the Library, torn in the Powerhouse. */
  const V={fresh:[440,180],clock:[440,200],global:[440,250],club:[440,230],cellar:[440,190],tube:[300,262],taste:[440,300]}[ch]||[440,220],
   amp={clock:.3,cellar:1.4,club:1}[ch]??.8,vx=V[0],vy=V[1];let o='';
  for(let i=-30;i<=30;i++){const x=vx+i*i*Math.sign(i)*1.9+i*14;o+=`<path class=f d="M${vx+i*3} ${vy} L${x.toFixed(0)} 500"/>`}
  for(let k=1;k<=22;k++){const t=k/22,y=vy+(500-vy)*Math.pow(t,1.8);o+=`<path class=f d="M0 ${y.toFixed(1)} H880"/>`}
  for(let k=0;k<26;k++){const t=k/25,y=vy*t;let d=`M0 ${y.toFixed(1)}`;for(let j=1;j<=20;j++){const x=j/20*880,sw=amp*7*Math.sin(j/20*Math.PI*2+t*4)*Math.sin(t*Math.PI);d+=` L${x.toFixed(0)} ${(y+sw).toFixed(1)}`}o+=`<path class=w d="${d}"/>`}
  return`<svg class=op viewBox="0 0 880 500" preserveAspectRatio="xMidYMid meet">${o}</svg>`}
 function noise(){const host=document.querySelector('#hall .hx');if(!host||host.querySelector('canvas'))return;const c=document.createElement('canvas');c.className='nz';c.width=220;c.height=125;host.appendChild(c);
  const x=c.getContext('2d'),P=[[30,22,22,20],[158,18,18,28],[104,82,30,14]];let f=0;
  (function step(){if(!document.body.contains(c))return;f++;x.clearRect(0,0,220,125);const ph=(f%80)/80,toStripes=ph>.5;
   P.forEach(([px,py,pw,qh],k)=>{if(toStripes){const g=Math.min(1,(ph-.5)*4);x.fillStyle='#efebe2';for(let yy=0;yy<qh;yy+=3){const sw=1.2+Math.sin(yy*.4+f*.2+k)*.8*g;x.globalAlpha=.55;x.fillRect(px,py+yy,pw,sw)}}
    else{const id=x.createImageData(pw,qh);for(let i=0;i<id.data.length;i+=4){const v=Math.random()*255;id.data[i]=id.data[i+1]=id.data[i+2]=v;id.data[i+3]=90}x.globalAlpha=1;x.putImageData(id,px,py)}});
   setTimeout(()=>requestAnimationFrame(step),125)})()}
 function extras(ch){const m=typeof HALLMEDIA!=='undefined'&&HALLMEDIA[ch];if(ch==='cellar')setTimeout(noise,50);if(!m)return'';return''}
 return{mount(el,ch,svg){el.innerHTML=`<div class=hw>${opart(ch)}${svg}<div class=hx>${extras(ch)}</div><div class=hl></div></div>`;const l=el.querySelector('.hl');render(l,ch);bind(l,ch);clearInterval(el._iv);el._iv=setInterval(()=>render(l,ch),20000)}};
})();

/* ============================================================ state from the radio */
let data = null, lastNow = "", an = null, actx = null, tT = 0, idle = 0, swT = 0;
const station = () => data?.stations.find(s => s.id === S.ch) || data?.stations[0];
function flash(s) { const t = $("#toast"); t.textContent = s; t.classList.add("on"); clearTimeout(tT); tT = setTimeout(() => t.classList.remove("on"), 1800) }
function wake() { R.classList.remove("idle"); clearTimeout(idle); idle = setTimeout(() => { if (S.on && !$$("#qp.on,#info.on").length) R.classList.add("idle") }, 4500) }
function sweep(w) { const e = $("#sweep"); e.textContent = w; e.style.fontSize = Math.min(19, 92 / (w.length * .66)) + "vw"; e.classList.remove("fly"); void e.offsetWidth; e.classList.add("fly"); VZ.kick(); clearTimeout(swT); swT = setTimeout(() => e.classList.remove("fly"), 1300) }
async function poll() {
  try { data = await fetch(BASE + "/api/stations", { cache: "no-store" }).then(r => r.json()) } catch { $("#lv").textContent = L("off"); R.classList.add("offair"); return }
  R.classList.remove("offair"); if (!data.stations.some(s => s.id === S.ch)) S.ch = data.stations[0].id;
  $$("[data-c]").forEach(b => { const s = data.stations.find(x => x.id === b.dataset.c); if (!s) { b.hidden = true; return } b.title = s.name; const f = b.querySelector(".fn"); if (f) f.textContent = s.name });
  render() }
function coverFor(n) {
  return new Promise(res => {
    if (n.cover) { const im = new Image(); im.crossOrigin = "anonymous"; im.onload = () => res(im); im.onerror = () => res(blankCover(n)); im.src = `${BASE}/api/cover/${n.id}` } else res(blankCover(n)) }) }
function blankCover(n) { /* no artwork: the artist's name, set in the house type */
  const c = document.createElement("canvas"); c.width = c.height = 512; const x = c.getContext("2d"); x.fillStyle = "#121216"; x.fillRect(0, 0, 512, 512);
  x.fillStyle = `hsl(${S.hue},60%,72%)`; let fs = 120; x.font = `800 ${fs}px 'Roboto Flex', Arial, sans-serif`; const w = (n.artist || "rrradio").split(" ");
  while (fs > 30 && Math.max(...w.map(s => x.measureText(s).width)) > 440) { fs -= 6; x.font = `800 ${fs}px 'Roboto Flex', Arial, sans-serif` }
  w.forEach((s, i) => x.fillText(s, 36, 80 + fs + i * fs * .92)); return c }
async function render() {
  const s = station(); if (!s) return;
  $$("[data-c]").forEach(e => e.classList.toggle("on", e.dataset.c === S.ch)); const chip = $(`#chs [data-c=${S.ch}]`), chi = $("#chi"); if (chip) { chi.style.left = chip.offsetLeft + "px"; chi.style.width = chip.offsetWidth + "px" }
  const n = s.now || {}; $("#ttl").textContent = n.title || s.name; $("#art").textContent = n.artist || ""; $("#why").textContent = `${s.name} · ${L("live")}${s.listeners >= 25 ? " · " + L("listening").replace("{n}", s.listeners) : ""}`;
  $("#ql").innerHTML = (s.next || []).map(q => `<div class=qi2><b>${esc(q.title)}</b><span>${esc(q.artist)}</span></div>`).join("") || `<p class=m>${L("picked")}</p>`;
  const key = S.ch + ":" + (n.id || ""); if (key === lastNow) return; lastNow = key;
  const im = await coverFor(n); if (lastNow !== key) return; const a = VZ.prep(im); S.P = S.A || a; S.A = a; S.trT = performance.now(); VZ.tint(a);
  if ("mediaSession" in navigator) navigator.mediaSession.metadata = new MediaMetadata({ title: n.title || s.name, artist: n.artist || "rrradio", album: "rrradio · " + s.name, artwork: n.cover ? [{ src: `${BASE}/api/cover/${n.id}`, sizes: "512x512" }] : [{ src: "icon.png", sizes: "512x512" }] }) }
function tick() { /* the bar only shows where the track is; a radio can't be scrubbed */
  const n = station()?.now; if (!n || !n.dur) return; const el = clamp(Date.now() / 1000 - n.started, 0, n.dur);
  $("#t1").textContent = fm(el); $("#t2").textContent = fm(n.dur); $("#sb i").style.width = (el / n.dur * 100).toFixed(2) + "%";
  if (el >= n.dur - .5) poll() }

/* ============================================================ listening */
function audioGraph() { if (actx) return; try { actx = new (window.AudioContext || window.webkitAudioContext)(); const src = actx.createMediaElementSource(au); an = actx.createAnalyser(); an.fftSize = 256; an.smoothingTimeConstant = .7; src.connect(an); an.connect(actx.destination); VZ.attach(an) } catch (e) { logErr(e) } }
function listen() { const s = station(); if (!s) return; au.src = `${BASE}/stream/${s.id}.mp3?t=${Date.now()}`; audioGraph(); actx?.resume(); au.play().catch(() => { }); S.on = true; $("#gate").classList.add("off"); $("#pp").classList.add("wait"); wake() }
function stop() { au.pause(); au.removeAttribute("src"); au.load(); S.on = false; $("#pp").classList.add("paused"); R.classList.remove("idle") }
au.addEventListener("playing", () => { const p = $("#pp"); p.classList.remove("paused", "wait"); $("#lv").textContent = L("lv") });
let retry = 0; const recover = () => { if (!S.on) return; $("#pp").classList.add("wait"); setTimeout(() => S.on && listen(), Math.min(8000, 1000 * ++retry)) };
au.addEventListener("error", recover); au.addEventListener("ended", recover);
function setC(c) { if (c === S.ch) return; seenSt.add(c); if (seenSt.size === 3) setTimeout(() => nudge("tour"), 4000); S.mvD = KEYS.indexOf(c) >= KEYS.indexOf(S.ch) ? 1 : -1; S.mvT = performance.now(); S.ch = c; keep("rr-ch", c); sweep(station()?.name || SHORT[c]); render(); if (S.on) listen() }
au.volume = (+(keep("rr-vol") ?? 80)) / 100; $("#vl").value = Math.round(au.volume * 100); $("#vl").oninput = e => { au.volume = e.target.value / 100; keep("rr-vol", e.target.value) };

/* ============================================================ nudges: a little at a time, only after you settled in */
const SITE = "https://antonalter.github.io/rrradio/", onSite = /\/radio\/?$/.test(location.pathname) && !location.port;
const extUrl = () => onSite ? "../downloads/rrradio-extension.zip" : (data?.extension ? BASE + data.extension : SITE + "downloads/rrradio-extension.zip");
const NUDGE = {
  skip: [L("n_skip"), L("l_skip"), () => extUrl()],
  stay: [L("n_stay"), L("l_stay"), () => extUrl()],
  tour: [L("n_tour"), L("l_tour"), () => extUrl()],
  keep: [L("n_keep"), L("l_keep"), () => onSite ? "../#depot" : SITE + "#depot"]
};
let nudged = 0, lastNudge = 0, listenMs = 0, seenSt = new Set([S.ch]);
function nudge(k) {
  const n = +(keep("rr-n-" + k) || 0), now = Date.now(); if (n >= 2 || nudged >= 3 || now - lastNudge < 6e5 && k !== "skip") return;
  const [t, l, u] = NUDGE[k], e = $("#nudge"); e.querySelector("p").textContent = t; const a = e.querySelector("a"); a.textContent = l + " →"; a.href = u(); if (/\.zip$/.test(a.href)) a.setAttribute("download", ""); else a.removeAttribute("download");
  e.classList.add("on"); keep("rr-n-" + k, n + 1); nudged++; lastNudge = now; clearTimeout(e._t); e._t = setTimeout(() => e.classList.remove("on"), 14000) }
$("#nudge button").addEventListener("click", () => $("#nudge").classList.remove("on"));
setInterval(() => { if (S.on && !au.paused) { listenMs += 5000; if (listenMs === 8 * 6e4) nudge("stay"); if (listenMs === 25 * 6e4) nudge("keep") } }, 5000);
addEventListener("hashchange", () => { const h = location.hash.slice(1); if (KEYS.includes(h)) setC(h) });

/* ============================================================ wiring */
function panel(id, on) { $(id).classList.toggle("on", on ?? !$(id).classList.contains("on")) }
function infoFill() { const L = $("#ilong"), ss = data?.stations || []; L.innerHTML = `<p class=m>${L("any")}</p><p>${L("anyp")}</p><ul>${ss.map(s => `<li><a href="${BASE}/listen/${s.id}.m3u">${esc(s.name)}</a></li>`).join("")}</ul><p class=m>${L("pers")}</p><p>${L("persp")}</p><p><a class="bt on" href="${data?.extension ? BASE + data.extension : "downloads/rrradio-extension.zip"}">${L("get")}</a></p>` }
R.addEventListener("click", e => { const b = e.target.closest("button"); if (!b) return; if (b.dataset.c) setC(b.dataset.c) });
$("#gate").addEventListener("click", listen);
$("#pp").addEventListener("click", () => S.on ? stop() : listen());
$("#qb").addEventListener("click", () => panel("#qp")); $("#qx").addEventListener("click", () => panel("#qp", false));
["#inb", "#thp", "#logo"].forEach(id => $(id).addEventListener("click", () => { infoFill(); panel("#info", true) })); $("#ix").addEventListener("click", () => panel("#info", false));
$("#tvp").addEventListener("click", () => { S.vz = S.vz ? 0 : 1; keep("rr-vz", S.vz); $("#tvp").classList.toggle("on", !!S.vz); flash(S.vz ? L("von") : L("voff")) });
$("#tdy").addEventListener("click", () => { S.day = S.day ? 0 : 1; keep("rr-day", S.day); R.classList.toggle("day", !!S.day) });
addEventListener("keydown", e => { if (e.target.closest("input")) return; const k = e.key;
  if (k === " ") { e.preventDefault(); S.on ? stop() : listen() } else if (/^[1-7]$/.test(k)) setC(KEYS[+k - 1]); else if (k === "v") $("#tvp").click(); else if (k === "q") panel("#qp"); else if (k === "n" || k === "ArrowRight") nudge("skip"); else if (k === "Escape") { panel("#info", false); panel("#qp", false) } wake() });
addEventListener("pointermove", wake);
R.classList.toggle("day", !!S.day); $("#tvp").classList.toggle("on", !!S.vz);
VZ.init(); poll(); setInterval(poll, 10000); setInterval(tick, 500); addEventListener("resize", () => render());
